let container = document.getElementById("tsrOverviewContainer");

let wrapper = document.createElement("div");
wrapper.classList.add("row");
let sectionContainer = document.createElement("div");
sectionContainer.classList.add("container", "col-12", "col-sm-8", "col-md-8", "col-lg-9", "col-xxl-10", "my-5");
// sectionContainer.style.scrollBehavior = "smooth";
// sectionContainer.style.height = "75vh";

for (let i = 0; i < tsrOverviewData.length; i++) {
    let sectionDiv = document.createElement("div");
    sectionDiv.classList.add("mb-5", "mx-3");
    let sectionObj = tsrOverviewData[i];

    // let sectionHeader = document.createElement("div");
    // sectionHeader.classList.add("card-header");
    // sectionHeader.style.backgroundColor = "aliceblue";
    // sectionHeader.style.fontSize = "20px";
    // sectionHeader.style.fontWeight = "400";


    // sectionHeader.style.color = "white";
    let sectionHeadingLink = document.createElement("a");
    sectionHeadingLink.classList.add("tsrSectionHeading");
    sectionHeadingLink.href = "#" + sectionObj.section.url;

    let sectionHeading = document.createElement("h5");
    sectionHeading.innerHTML = sectionObj.section.title;
    sectionHeading.id = sectionObj.section.title.replaceAll(" ", "");
    // sectionHeading.style.textDecoration = "underline";

    sectionHeadingLink.appendChild(sectionHeading);

    let hr = document.createElement("hr");

    sectionHeadingLink.appendChild(hr);

    // sectionHeadingLink.innerHTML = section.sectionTitle;

    // sectionHeader.appendChild(sectionHeadingLink);


    sectionDiv.appendChild(sectionHeadingLink);

    // let sectionBody = document.createElement("div");
    // sectionBody.classList.add("card-body", "pt-0");

    let cards = sectionObj.cards;
    let noOfRows = cards.length % 3 == 0 ? (cards.length / 3) : (cards.length / 3) + 1;
    for (let j = 0; j < noOfRows; j++) {
        let row = document.createElement("div");
        row.classList.add("row", "mb-3");
        for (let k = 0; k <= 2; k++) {
            let cardIdx = (j * 3) + k;
            if (cards[cardIdx]) {
                let cardContainer = document.createElement("div");
                cardContainer.classList.add("col-12", "col-md-6", "col-lg-4", "mb-3", "mb-lg-0");

                let card = document.createElement("div");
                card.classList.add("card", "h-100", "shadow-lg");
                if (k + 1 <= 2) {
                    card.classList.add("border-end");
                }

                let cardBody = document.createElement("div");
                cardBody.classList.add("card-body", "h-100");


                let a = document.createElement("a");
                let h5 = document.createElement("h5");
                h5.classList.add("card-title");
                h5.innerText = cards[cardIdx].title;
                h5.id = cards[cardIdx].title;
                a.href = cards[cardIdx].url;
                a.appendChild(h5);

                let ul = document.createElement("ul");
                ul.classList.add("card-text", "mb-0");

                let urls = cards[cardIdx].urls;

                for (let l = 0; l < urls.length; l++) {
                    let li = document.createElement("li");
                    if (urls[l].modal != undefined || urls[l].modal != null) {
                        let imgUrl = urls[l].imgSrc;
                        // li.innerHTML = urls[l].text + "&nbsp;" + '<i class="fas fa-external-link-alt"></i>';
                        li.innerHTML = urls[l].text + "&nbsp;" + '<i class="far fa-image"></i>';
                        li.onclick = function () { createImgDialog(imgUrl) };
                        li.style.cursor = "pointer";
                    }
                    else {
                        if (urls[l].url != null) {
                            let a = document.createElement("a");
                            a.innerHTML = urls[l].text + '&nbsp;' + '<i class="fas fa-link"></i>' + "<br>";
                            a.href = urls[l].url;
                            a.classList.add("tsrLinks");
                            li.appendChild(a);
                        }
                        else {
                            li.innerText = urls[l].text;
                        }
                    }
                    ul.appendChild(li);
                }

                cardBody.appendChild(a);
                cardBody.appendChild(ul);

                card.appendChild(cardBody);

                cardContainer.appendChild(card);
                row.appendChild(cardContainer);
            }

        }

        // sectionBody.appendChild(row);
        sectionDiv.appendChild(row);
    }
    // sectionDiv.appendChild(sectionBody);
    sectionContainer.appendChild(sectionDiv);


}


let navMenuContainer = document.createElement("div");
navMenuContainer.classList.add("d-none", "d-sm-flex", "col-sm-4", "col-md-4", "col-lg-3", "col-xxl-2", "border-start");
let navMenu = document.createElement("div");
navMenu.classList.add("d-none", "d-sm-flex", "my-5", "flex-column", "position-fixed");

let navMenuTitle = document.createElement("span");
navMenuTitle.innerHTML = "On this page <br><br> ";
navMenuTitle.style.fontWeight = "bold";

navMenu.appendChild(navMenuTitle);

for (let i = 0; i < tsrOverviewData.length; i++) {
    let a = document.createElement("a");

    a.href = "#" + tsrOverviewData[i].section.title.replaceAll(" ", "");
    a.innerHTML = tsrOverviewData[i].section.title + "<br>";
    a.classList.add("my-1", "tsrLinks");
    navMenu.appendChild(a);
}

wrapper.appendChild(sectionContainer);

navMenuContainer.appendChild(navMenu);
wrapper.appendChild(navMenuContainer);
container.appendChild(wrapper);


function createImgDialog(imgUrl) {
    // let dialog = document.getElementById("tsrImageViewer");
    let dialog = document.createElement("dialog");
    dialog.id = "tsrImageViewer";
    dialog.classList.add("border");

    let closeDiv = document.createElement("div");
    let closeBtn = document.createElement("button");
    closeBtn.classList.add("btn-close");
    closeBtn.onclick = closeDialog;

    closeDiv.setAttribute("align", "right");
    closeDiv.appendChild(closeBtn);

    let imgDiv = document.createElement("div");
    imgDiv.style.overflowX = "auto";

    let img = document.createElement("img");
    img.classList.add("m-3")
    img.src = imgUrl;

    imgDiv.appendChild(img);

    dialog.appendChild(closeDiv);
    dialog.appendChild(imgDiv);

    document.body.appendChild(dialog);

    dialog.showModal();
}

function closeDialog() {
    let dialog = document.getElementById("tsrImageViewer");
    dialog.close();
    document.body.removeChild(dialog);
}


